    # [MaesterParameter] on a test parameter.
    ParameterAttribute = @{
        Kind = @{
            Type        = 'string'
            Required    = 'Always'
            ValuesFrom  = 'ParameterKindRegistry'
            Pattern     = '^[A-Za-z][A-Za-z0-9]*(\.[A-Za-z][A-Za-z0-9]*)+$'
            Description = 'Name of an entry in the parameter-kind registry, for example Entra.Group.'
        }
